import { join, relative, resolve } from "../../platform/compat/path/index.js";
import { isNotFoundError } from "../../platform/compat/fs.js";
import { serverLogger } from "../../utils/index.js";
import { capitalizeSeparatedWords } from "../../utils/case-utils.js";
import { toBase64Url } from "../../utils/path-utils.js";
import { runtime } from "../../platform/adapters/detect.js";
import { createError, toError } from "../../errors/index.js";
import { extractExportNames } from "./export-extractor.js";
import { shortHash } from "../../utils/hash-utils.js";
import { hasClientFileName, hasUseClientDirective, hasUseServerDirective } from "./page-island.js";
import { isWithinDirectory } from "../../security/path-validation.js";
class DuplicateClientComponentIdError extends Error {
}
export async function analyzeComponent(filePath, fs) {
    const content = await fs.readFile(filePath);
    const hasUseClient = hasUseClientDirective(content);
    const hasUseServer = hasUseServerDirective(content);
    // Determine component type: directive takes precedence over file naming convention
    const type = hasUseClient || hasClientFileName(filePath) ? "client" : "server";
    const exports = await extractExportNames(content, filePath);
    return {
        type,
        filePath,
        exports,
        id: generateComponentId(filePath),
        contentHash: await shortHash(content),
        hasUseClient,
        hasUseServer,
    };
}
function generateComponentId(filePath) {
    const normalized = filePath.replace(/\.(tsx?|jsx?)$/, "").replace(/\.(client|server)$/, "");
    const parts = normalized.split("/");
    const fileName = parts.at(-1);
    if (fileName === "index") {
        return toPascalCase(parts.at(-2) ?? "Unknown");
    }
    return toPascalCase(fileName ?? "Unknown");
}
function toPascalCase(str) {
    return capitalizeSeparatedWords(str, /[-_\s]+/, "");
}
export async function buildClientManifest(projectDir, appDir = "app", fs) {
    const manifest = new Map();
    const projectRoot = resolve(projectDir);
    const normalizedAppDir = appDir.replace(/^\/+|(?<!\/)\/+$/g, "") || "app";
    const appPath = join(projectDir, normalizedAppDir);
    const absoluteAppPath = resolve(projectRoot, normalizedAppDir);
    if (!isWithinDirectory(projectRoot, absoluteAppPath))
        return manifest;
    const fsAdapter = fs ?? (await getFsAdapter());
    if (!fsAdapter)
        return manifest;
    try {
        if (!await isCanonicallyContainedAppRoot(projectDir, appPath, fsAdapter)) {
            return manifest;
        }
        await walkDirectory(appPath, async (filePath) => {
            if (!/\.(tsx?|jsx?)$/.test(filePath))
                return;
            const analysis = await analyzeComponent(filePath, fsAdapter);
            if (analysis.type !== "client")
                return;
            const relativePath = relative(projectDir, filePath);
            const normalizedRelativePath = relativePath.replaceAll("\\", "/");
            const existing = manifest.get(analysis.id);
            if (existing && existing.rel !== normalizedRelativePath) {
                throw new DuplicateClientComponentIdError(`Duplicate client component ID "${analysis.id}" for "${existing.rel}" and "${normalizedRelativePath}"`);
            }
            manifest.set(analysis.id, {
                id: analysis.id,
                path: `/_veryfront/fs/${toBase64Url(filePath)}`,
                sourcePath: filePath,
                rel: normalizedRelativePath,
                contentHash: analysis.contentHash,
                exports: analysis.exports,
            });
            serverLogger.debug(`Found client component: ${analysis.id} at ${relativePath}`);
        }, fsAdapter);
    }
    catch (error) {
        if (error instanceof DuplicateClientComponentIdError)
            throw error;
        serverLogger.warn(`Failed to build client manifest:`, error);
    }
    return manifest;
}
/**
 * Confirm the lexically contained app root stays inside the project once
 * symlinks are resolved. An adapter must either declare
 * `symlinkSemantics: "none"` or provide canonical paths.
 */
async function isCanonicallyContainedAppRoot(projectRoot, appPath, fsAdapter) {
    const semantics = Object.getOwnPropertyDescriptor(fsAdapter, "symlinkSemantics");
    if (semantics && "value" in semantics && semantics.value === "none")
        return true;
    const realPath = fsAdapter.realPath?.bind(fsAdapter);
    if (!realPath)
        return false;
    try {
        const [canonicalProjectRoot, canonicalAppPath] = await Promise.all([
            realPath(projectRoot),
            realPath(appPath),
        ]);
        return isWithinDirectory(canonicalProjectRoot, canonicalAppPath);
    }
    catch (error) {
        // A missing app directory yields an empty manifest either way; any other
        // canonicalization failure fails closed.
        if (!isNotFoundError(error)) {
            serverLogger.warn(`Failed to canonicalize app directory:`, error);
        }
        return false;
    }
}
async function getFsAdapter() {
    try {
        const adapter = await runtime.get();
        return adapter.fs;
    }
    catch (error) {
        serverLogger.warn(`Failed to get file system adapter:`, error);
        return undefined;
    }
}
async function walkDirectory(dir, callback, fs) {
    try {
        if (!fs) {
            throw toError(createError({
                type: "config",
                message: "FileSystemAdapter is required for walkDirectory",
            }));
        }
        const entries = fs.readDir(dir);
        for await (const entry of entries) {
            const path = join(dir, entry.name);
            if (entry.isDirectory) {
                if (shouldSkipDirectory(dir, entry.name))
                    continue;
                await walkDirectory(path, callback, fs);
                continue;
            }
            if (entry.isFile) {
                await callback(path);
            }
        }
    }
    catch (error) {
        if (isNotFoundError(error))
            return;
        throw error;
    }
}
function shouldSkipDirectory(parentDir, name) {
    // Skip node_modules and hidden dirs, but allow .veryfront (excluding system subdirs)
    if (name === "node_modules")
        return true;
    if (name.startsWith(".") && name !== ".veryfront")
        return true;
    if (!parentDir.includes(".veryfront"))
        return false;
    return ["cache", "compiled", "tmp", "temp", "output", "optimized-images", "css"].includes(name);
}
